{
  "verses": [
    {
      "chapter": 2,
      "verse": 3,
      "text_ar": "بل ابتلعها كلها ولم تستقر في معدته، بل خرجت من فمه. فقال آدم: لنقُم ونذهب"
    },
    {
      "chapter": 2,
      "verse": 4,
      "text_ar": "ونرى ماذا حدث لهما. (إني أخشى) لعل العدو يهاجمهما في مكان ما."
    },
    {
      "chapter": 3,
      "verse": 1,
      "text_ar": "وذهبا كلاهما فوجدا هابيل مقتولاً، على يد قايين أخيه. وقال الله"
    },
    {
      "chapter": 3,
      "verse": 2,
      "text_ar": "لميخائيل رئيس الملائكة: (قل لآدم: لا تكشف السر الذي تعلمه لقايين ابنك، لأنه ابن غضب. ولكن لا تحزن، فإني سأعطيك ابناً آخر عوضاً عنه، وهو سيُظهر لك كل ما ستفعله. لا تخبره بشريء). هكذا تكلم رئيس الملائكة"
    },
    {
      "chapter": 3,
      "verse": 3,
      "text_ar": "مع آدم. ولكنه حفظ الكلام في قلبه، ومعه حواء أيضاً، مع أنهما حزنا على هابيل ابنهما."
    }
  ],
  "book_code": "APMO"
}
